// 路径字符串工具 (纯函数, 不引入 Tauri 运行时, 便于单测)。

/** 去掉结尾的分隔符 (`C:\a\` -> `C:\a`)。 */
export function stripTrailingSeparator(path: string): string {
  return path.replace(/[\\/]+$/, '');
}

/** 取路径最后一段 (文件名或目录名); 结尾分隔符会被忽略。 */
export function baseName(path: string): string {
  const trimmed = stripTrailingSeparator(path);
  return trimmed.split(/[\\/]/).pop() ?? path;
}

/** 统一成正斜杠, 用于大小写不敏感比较与相对路径计算。 */
export function toPosix(path: string): string {
  return path.replace(/\\/g, '/');
}

/** 获取文件相对根目录的父目录; 文件不在根目录内时返回 null。 */
export function relativeDirectoryPath(rootPath: string, filePath: string): string | null {
  const root = toPosix(stripTrailingSeparator(rootPath));
  const file = toPosix(stripTrailingSeparator(filePath));
  const prefix = `${root.toLowerCase()}/`;
  if (!file.toLowerCase().startsWith(prefix)) return null;

  const relativeFile = file.slice(root.length + 1);
  const segments = relativeFile.split('/').filter(Boolean);
  if (segments.length === 0) return null;
  segments.pop();
  return segments.join('/');
}

/** 两个路径是否指向同一个位置 (Windows 大小写不敏感)。 */
export function samePath(a: string, b: string): boolean {
  return toPosix(a).toLowerCase() === toPosix(b).toLowerCase();
}

/** 项目内的相对路径 (正斜杠)。 */
export function projectRelativePath(projectPath: string, filePath: string): string {
  const base = toPosix(stripTrailingSeparator(projectPath));
  const abs = toPosix(filePath);
  if (abs === base) return '.';
  if (abs.toLowerCase().startsWith(`${base.toLowerCase()}/`)) return abs.slice(base.length + 1);
  return abs;
}

/**
 * 浏览器菜单里"复制路径"的取值: 场景去掉 `game/scene/`, 资源去掉 `game/` 与可省略的第一级
 * 目录 —— 复制出来的是用户写脚本时真正要填的那个相对路径, 而不是磁盘上的完整位置。
 *
 * **这是"相对路径"的唯一口径**: 右键菜单、复制到剪贴板、以及"把文件拖进编辑器"都从这里取,
 * 三处必须给出同一个字符串, 否则用户拖进去的和粘进来的会对不上。
 */
export function browserRelativePath(projectPath: string, filePath: string): string {
  const relative = projectRelativePath(projectPath, filePath).replace(/^\/+/, '');
  const scenePrefix = 'game/scene/';
  if (relative.toLowerCase().startsWith(scenePrefix)) return relative.slice(scenePrefix.length);

  const gamePrefix = 'game/';
  if (!relative.toLowerCase().startsWith(gamePrefix)) return relative;
  const resourcePath = relative.slice(gamePrefix.length);
  const segments = resourcePath.split('/');
  return segments.length > 1 ? segments.slice(1).join('/') : resourcePath;
}

/** 用平台分隔符拼接目录与名称。 */
export function joinPath(directory: string, ...segments: string[]): string {
  return [stripTrailingSeparator(directory), ...segments].filter((part) => part !== '').join('\\');
}

/**
 * 长名称中间省略, 保留开头与扩展名后缀 (`a/b/c/very-long-name.txt` -> `a/b...name.txt`)。
 *
 * 放在这里而不是某个组件里: 文件树与仓库页都要用, 而 `.svelte` 实例脚本里的 `export function`
 * 是导不出来的 (Svelte 只允许从 `<script module>` 导出)。
 */
export function middleEllipsis(text: string, maxLen: number): string {
  if (text.length <= maxLen) return text;
  const dot = text.lastIndexOf('.');
  const hasExt = dot > 0 && dot < text.length - 1;
  const ext = hasExt ? text.slice(dot) : '';
  const stem = hasExt ? text.slice(0, dot) : text;
  const avail = maxLen - ext.length - 3;
  if (avail < 4) return `${text.slice(0, Math.max(1, maxLen - 3))}...`;
  const keepHead = Math.ceil(avail / 2);
  const keepTail = avail - keepHead;
  return `${stem.slice(0, keepHead)}...${stem.slice(stem.length - keepTail)}${ext}`;
}

/**
 * 把用户输入的项目名整理成可用的文件夹名。
 *
 * 去掉路径分隔符与 Windows 保留字符, 合并空白, 去掉首尾的点与空格 (Windows 上 `name.` 与
 * `name ` 都会指向 `name`)。**不**在名字为空时编造名字 —— 那由调用方校验。
 */
export function sanitizeFolderName(name: string): string {
  return name
    .replace(/[\\/:*?"<>|]/g, '_')
    .replace(/\s+/g, ' ')
    .replace(/^[.\s]+|[.\s]+$/g, '')
    .slice(0, 80);
}
